     internal_pIntSync100_din(0) <= to_X01(pIntSync100);
  internal_aIntClk10_din(0) <= to_X01(aIntClk10);
  internal_aDramReady_din(0) <= to_X01(aDramReady);
internal_Routing_aSource0 <= (others => '0');
