   -------------------------------------------------------------------------
   -- This process synchronizes the async bus reset to the bus clock domain
   -------------------------------------------------------------------------
   SynchronizeBusReset : process(BusClkThruBuf)
   begin
     if rising_edge(BusClkThruBuf) then
       bBusReset_ms <= to_StdLogic(aBusReset);
       bBusReset <= bBusReset_ms;
     end if;
   end process SynchronizeBusReset;

